import json

with open('/sdcard/Nexus_Brain/nexus_vault/_master_manifest_clean.json') as f:
    data = json.load(f)

proposed = [
    'Master_Social_Media_Outreach',
    'Master_Outreach_Automation_Tools',
    'Master_Sales_Team_Scaling',
    'Master_Sales_Psychology_Influence',
    'Master_Monetization_Business_Model',
    'Master_Negotiation_And_Objection_To_Price',
    'Master_Content_AI_And_Automation',
]

print('=== Proposed vs Existing in Manifest ===')
for p in proposed:
    matches = []
    for m in data['masters']:
        # direct match
        if m['master_name'] == p.replace('Master_',''):
            matches.append(f"  EXACT: master_id {m['master_id']} ({m['concept_count']} concepts)")
        # partial overlap key words
        p_words = set(p.lower().replace('master_','').split('_'))
        m_words = set(m['master_name'].lower().split('_'))
        overlap = p_words & m_words
        if len(overlap) >= 3:
            matches.append(f"  SIMILAR: master_id {m['master_id']} '{m['master_name']}' ({m['concept_count']} concepts, overlap={overlap})")
    if not matches:
        print(f'{p} -> NO COLLISION')
    else:
        print(f'{p}:')
        for ma in matches:
            print(ma)

print()
print('=== Overlapping masters detail ===')
for m in data['masters']:
    if m['master_id'] in [5]:
        print(f"Sales_Psychology_Tactics (id {m['master_id']}, {m['concept_count']} concepts)")
        for c in m['concepts']:
            print(f"  - {c}")
    if m['master_id'] in [7]:
        print(f"Social_Media_Platform_Strategy (id {m['master_id']}, {m['concept_count']} concepts)")
        for c in m['concepts']:
            print(f"  - {c}")
    if m['master_id'] in [10]:
        print(f"Pricing_Offers_Monetization (id {m['master_id']}, {m['concept_count']} concepts)")
        for c in m['concepts']:
            print(f"  - {c}")
    if m['master_id'] in [12]:
        print(f"AI_Automation_Workflow (id {m['master_id']}, {m['concept_count']} concepts)")
        for c in m['concepts']:
            print(f"  - {c}")
    if m['master_id'] in [23]:
        print(f"Content_Monetization_Models (id {m['master_id']}, {m['concept_count']} concepts)")
        for c in m['concepts']:
            print(f"  - {c}")

